-- Phase 33 — Việc 1 (lệnh "Xử lý 3 xác nhận"): migrate 30 AI_PROMPTS vào
-- bảng `prompts`, publish thẳng.
--
-- Nguồn: src/data/khong-gian-ai/index.ts, mảng AI_PROMPTS (30 mục, id
-- prompt-001..prompt-030). Đã kiểm tra không trùng lặp với 2 dòng Published
-- hiện có (prompt_1/prompt_2, slug viral-content/phan-tich-doi-thu) — 0
-- overlap về cả `id` lẫn `data.slug`.
--
-- MAPPING field (AiPrompt tĩnh -> AdminPrompt/bảng prompts):
--   id/slug/title/category/description  -> giữ nguyên tên
--   prompt                               -> content
--   featured                             -> giữ nguyên
--
-- 2 field KHÔNG có trong nguồn tĩnh, KHÔNG fabricate theo từng dòng:
--   exampleOutput -> '' (nguồn không có ví dụ kết quả nào)
--   tags          -> [] (nguồn không có tag tự do; xem sourceToolSlug/
--                    sourceNeedSlug bên dưới thay vì bịa tag)
--
-- 2 field bắt buộc trong UI Admin nhưng KHÔNG có trong nguồn, đặt MẶC ĐỊNH
-- ĐỒNG LOẠT cho cả 30 dòng (không phân loại riêng từng câu vì không có dữ
-- liệu gốc để phân loại — ghi rõ đây là default, không phải phân loại thật):
--   level -> 'Cơ bản'
--   tier  -> 'Free' (Portal hiện KHÔNG có gate nào theo tier — đã grep xác
--            nhận /portal/prompts không đọc field này để chặn quyền truy
--            cập — nên Free là lựa chọn trung tính, không khoá nội dung
--            vừa publish)
--   copyCount -> 0 (đếm thật bắt đầu từ 0, không bịa số liệu)
--
-- GIỮ LẠI (không phải field chuẩn của bảng, nhưng là dữ liệu quan hệ thật,
-- không muốn âm thầm mất khi migrate) 2 key jsonb thêm ngoài schema:
--   sourceToolSlug, sourceNeedSlug — đúng `toolSlug`/`needSlug` gốc, cho
--   biết prompt này vốn gắn với Tool/Need nào ở `/portal/aiworkspace/[slug]`.
--   Đây CHỈ LÀ TRUY XUẤT LỊCH SỬ — mảng tĩnh `AI_PROMPTS` vẫn là nguồn thật
--   đang chạy cho khối "Prompt liên quan" ở trang chi tiết Tool/Need (xem
--   ToolDetailPage/NeedCategoryPage), KHÔNG đổi sang đọc bảng `prompts` ở
--   việc này (ngoài phạm vi yêu cầu, cần xác nhận riêng nếu muốn hợp nhất
--   2 nguồn prompt lại thành 1).
--
-- Kết quả: 30 dòng migrate mới sẽ xuất hiện thêm ở `/portal/prompts` (qua
-- <AdminPromptsSection/>, đọc mọi dòng Published của bảng `prompts`) —
-- KHÔNG thay thế nội dung "Prompt liên quan" hiện có ở trang Tool/Need chi
-- tiết (vẫn đọc AI_PROMPTS tĩnh như trước, không đổi).
--
-- "order" tiếp nối sau 2 dòng có sẵn (order chưa dùng cho 2 dòng cũ, mặc
-- định 0 — bắt đầu từ 10 để không trộn thứ tự với dữu liệu Admin biên tập
-- tay từ trước).

insert into public.prompts (id, data, status, "order") values ('prompt-001', '{"id":"prompt-001","slug":"viet-bai-facebook-gioi-thieu-san-pham","title":"Viết bài Facebook giới thiệu sản phẩm","category":"Viết nội dung","description":"Tạo bài viết Facebook hấp dẫn để giới thiệu sản phẩm, kèm hook mở đầu và call-to-action.","content":"Bạn là chuyên gia viết nội dung mạng xã hội cho thị trường Việt Nam. Hãy viết một bài Facebook để giới thiệu sản phẩm sau:\n\nTên sản phẩm: [TÊN SẢN PHẨM]\nĐặc điểm nổi bật: [MÔ TẢ ĐẶC ĐIỂM]\nKhách hàng mục tiêu: [ĐỐI TƯỢNG]\nGiá bán: [GIÁ]\n\nYêu cầu:\n- Mở đầu bằng một câu hook gây chú ý (đặt câu hỏi hoặc đưa ra con số ấn tượng)\n- Nêu rõ vấn đề khách hàng đang gặp phải\n- Giải thích sản phẩm giải quyết vấn đề đó thế nào\n- Kết thúc bằng call-to-action rõ ràng (comment, inbox, hoặc nhấn link)\n- Độ dài 150-250 từ, giọng văn gần gũi, tự nhiên như người thật viết\n- Thêm 3-5 emoji phù hợp tại các vị trí hợp lý","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":true,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 10) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-002', '{"id":"prompt-002","slug":"viet-email-chao-hang-chuyen-nghiep","title":"Viết email chào hàng chuyên nghiệp","category":"Viết nội dung","description":"Tạo email chào hàng thuyết phục, cá nhân hóa và có tỷ lệ phản hồi cao.","content":"Bạn là chuyên gia bán hàng B2B với 10 năm kinh nghiệm viết email lạnh (cold email) hiệu quả. Hãy viết một email chào hàng chuyên nghiệp với thông tin sau:\n\nNgành nghề người nhận: [NGÀNH NGHỀ]\nVấn đề họ thường gặp: [VẤN ĐỀ]\nSản phẩm/dịch vụ tôi muốn giới thiệu: [SẢN PHẨM]\nLợi ích cụ thể: [LỢI ÍCH]\n\nYêu cầu:\n- Tiêu đề email ngắn gọn, cá nhân hóa, không dùng từ spam\n- Mở đầu nhắc tới vấn đề cụ thể của họ (không nói về tôi trước)\n- Giới thiệu giải pháp ngắn gọn trong 2-3 câu\n- Đưa ra bằng chứng hoặc con số cụ thể nếu có\n- Kết thúc bằng CTA đơn giản: đề xuất cuộc gọi 15 phút hoặc demo\n- Tổng độ dài không quá 150 từ, giọng văn lịch sự nhưng tự tin","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":true,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 11) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-003', '{"id":"prompt-003","slug":"tom-tat-tai-lieu-dai-5-diem-chinh","title":"Tóm tắt tài liệu dài thành 5 điểm chính","category":"Nghiên cứu","description":"Trích xuất nhanh 5 insight quan trọng nhất từ tài liệu dài hoặc PDF.","content":"Bạn là trợ lý nghiên cứu chuyên nghiệp. Tôi sẽ cung cấp cho bạn một đoạn văn bản hoặc tài liệu dài. Hãy phân tích và tóm tắt theo yêu cầu sau:\n\n[DÁN NỘI DUNG TÀI LIỆU VÀO ĐÂY]\n\nSau khi đọc, hãy trả lời theo cấu trúc:\n1. Chủ đề chính: (1 câu mô tả tài liệu nói về gì)\n2. Năm điểm chính: (liệt kê 5 ý quan trọng nhất, mỗi ý 1-2 câu)\n3. Số liệu đáng chú ý: (nêu các con số, thống kê quan trọng nếu có)\n4. Kết luận hoặc khuyến nghị: (tóm tắt kết luận của tài liệu)\n5. Câu hỏi cần làm rõ thêm: (2-3 điểm bạn cần tìm hiểu thêm về chủ đề này)\n\nViết bằng tiếng Việt, ngắn gọn và dễ hiểu.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":true,"copyCount":0,"status":"Published","sourceToolSlug":"claude","sourceNeedSlug":"nghien-cuu"}'::jsonb, 'Published', 12) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-004', '{"id":"prompt-004","slug":"len-ke-hoach-noi-dung-30-ngay","title":"Lên kế hoạch nội dung 30 ngày","category":"Viết nội dung","description":"Tạo lịch nội dung chi tiết cho 30 ngày với đa dạng chủ đề và định dạng bài viết.","content":"Bạn là chiến lược gia nội dung (content strategist) chuyên về mạng xã hội tại Việt Nam. Hãy tạo kế hoạch nội dung cho 30 ngày tới với thông tin sau:\n\nLĩnh vực/ngành: [LĨNH VỰC]\nNền tảng đăng bài: [FACEBOOK / INSTAGRAM / TIKTOK / LINKEDIN]\nMục tiêu: [XÂY DỰNG THƯƠNG HIỆU / BÁN HÀNG / TĂNG FOLLOW]\nTần suất đăng: [SỐ BÀI/TUẦN]\n\nHãy lập bảng kế hoạch bao gồm:\n- Ngày đăng bài\n- Chủ đề bài viết\n- Loại nội dung (tip, story, giới thiệu sản phẩm, hỏi đáp, behind-the-scenes...)\n- Ý tưởng hook mở đầu\n- Hashtag gợi ý\n\nĐảm bảo đa dạng chủ đề, không lặp lại quá nhiều và xen kẽ giữa nội dung giáo dục, giải trí và bán hàng theo tỷ lệ 60-20-20.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":true,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 13) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-005', '{"id":"prompt-005","slug":"phan-tich-diem-manh-yeu-doi-thu","title":"Phân tích điểm mạnh/yếu của đối thủ","category":"Marketing","description":"Nghiên cứu toàn diện về đối thủ cạnh tranh để tìm ra cơ hội cho sản phẩm của mình.","content":"Hãy nghiên cứu và phân tích đối thủ cạnh tranh sau đây cho tôi:\n\nTên đối thủ: [TÊN CÔNG TY/THƯƠNG HIỆU]\nNgành: [NGÀNH NGHỀ]\nThị trường: [VIỆT NAM / ĐÔNG NAM Á / ...]\n\nPhân tích theo các tiêu chí:\n1. Sản phẩm/dịch vụ: họ cung cấp gì, giá như thế nào\n2. Điểm mạnh rõ ràng: họ đang làm tốt điều gì\n3. Điểm yếu/hạn chế: khách hàng phàn nàn điều gì về họ\n4. Chiến lược marketing: họ đang dùng kênh nào, thông điệp gì\n5. Tệp khách hàng: họ đang phục vụ ai\n6. Cơ hội cho tôi: tôi có thể cạnh tranh hoặc khác biệt thế nào\n\nDùng nguồn thông tin từ website, review khách hàng, mạng xã hội và tin tức gần đây. Trích dẫn nguồn cho mỗi thông tin.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"perplexity","sourceNeedSlug":"marketing"}'::jsonb, 'Published', 14) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-006', '{"id":"prompt-006","slug":"viet-kich-ban-video-youtube","title":"Viết kịch bản video YouTube","category":"Làm video","description":"Tạo kịch bản video YouTube hoàn chỉnh với hook, nội dung và outro chuyên nghiệp.","content":"Bạn là người viết kịch bản YouTube chuyên nghiệp với kinh nghiệm tạo ra các video đạt hàng triệu lượt xem. Hãy viết kịch bản cho video với thông tin:\n\nChủ đề video: [CHỦ ĐỀ]\nĐộ dài mục tiêu: [5 / 10 / 15 PHÚT]\nĐối tượng xem: [MÔ TẢ KHÁN GIẢ]\nMục tiêu video: [GIÁO DỤC / BÁN HÀNG / XÂY DỰNG THƯƠNG HIỆU]\n\nKịch bản cần có:\n- HOOK (0-15 giây): câu mở đầu gây tò mò hoặc hứa hẹn giá trị\n- GIỚI THIỆU (15-45 giây): bạn là ai, video này cho ai\n- NỘI DUNG CHÍNH: chia thành 3-5 phần rõ ràng với transition\n- CTA GIỮA VIDEO: nhắc subscribe hoặc tương tác nhẹ nhàng\n- KẾT LUẬN: tóm tắt bài học chính\n- OUTRO: CTA cuối và gợi ý xem video tiếp theo\n\nViết theo dạng lời nói tự nhiên, không quá formal, kèm ghi chú [B-ROLL] hoặc [GRAPHICS] tại các điểm cần hình ảnh minh họa.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":true,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"lam-video"}'::jsonb, 'Published', 15) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-007', '{"id":"prompt-007","slug":"viet-mo-ta-san-pham-ban-hang-online","title":"Viết mô tả sản phẩm bán hàng online","category":"Viết nội dung","description":"Tạo mô tả sản phẩm hấp dẫn cho Shopee, Lazada, TikTok Shop hoặc website.","content":"Bạn là chuyên gia viết mô tả sản phẩm cho thương mại điện tử Việt Nam. Hãy viết mô tả sản phẩm đầy đủ cho:\n\nTên sản phẩm: [TÊN]\nDanh mục: [DANH MỤC]\nĐặc điểm kỹ thuật: [THÔNG SỐ]\nGiá bán: [GIÁ]\nNền tảng bán: [SHOPEE / LAZADA / TIKTOK SHOP / WEBSITE]\n\nViết theo cấu trúc:\n1. Tiêu đề sản phẩm: tối ưu từ khóa, bao gồm tên + đặc điểm nổi bật + thương hiệu (dưới 150 ký tự)\n2. Mô tả ngắn: 3-5 bullet points nêu lợi ích chính (không phải tính năng)\n3. Mô tả chi tiết: 200-400 từ, bắt đầu bằng pain point của khách hàng, sau đó giải thích sản phẩm giải quyết thế nào\n4. Thông số kỹ thuật: bảng hoặc danh sách rõ ràng\n5. Hướng dẫn sử dụng: các bước đơn giản\n6. Cam kết/chính sách: đổi trả, bảo hành\n\nTối ưu cho tìm kiếm trên sàn TMĐT Việt Nam.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 16) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-008', '{"id":"prompt-008","slug":"nghien-cuu-xu-huong-thi-truong-moi-nhat","title":"Nghiên cứu xu hướng thị trường mới nhất","category":"Nghiên cứu","description":"Tìm hiểu xu hướng thị trường hiện tại với nguồn dẫn chứng cụ thể và dữ liệu cập nhật.","content":"Hãy nghiên cứu xu hướng thị trường hiện tại cho tôi trong lĩnh vực:\n\nLĩnh vực: [NGÀNH NGHỀ]\nKhu vực địa lý: [VIỆT NAM / ĐÔNG NAM Á / TOÀN CẦU]\nKhung thời gian: 6-12 tháng gần nhất\n\nCung cấp thông tin:\n1. Top 5 xu hướng lớn nhất hiện nay trong lĩnh vực này\n2. Số liệu tăng trưởng thị trường (kèm nguồn)\n3. Những thay đổi hành vi người tiêu dùng đáng chú ý\n4. Các đối thủ/thương hiệu đang tăng trưởng nhanh nhất\n5. Cơ hội kinh doanh chưa được khai thác\n6. Rủi ro và thách thức cần lưu ý\n\nMỗi điểm cần có nguồn dẫn chứng cụ thể (báo cáo, bài báo, dữ liệu). Ưu tiên nguồn từ năm nay hoặc năm ngoái.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"perplexity","sourceNeedSlug":"nghien-cuu"}'::jsonb, 'Published', 17) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-009', '{"id":"prompt-009","slug":"lap-ke-hoach-hoc-tap-3-thang","title":"Lập kế hoạch học tập 3 tháng","category":"Nghiên cứu","description":"Tạo lộ trình học tập chi tiết và khả thi cho bất kỳ kỹ năng hoặc lĩnh vực nào.","content":"Bạn là chuyên gia tư vấn học tập và phát triển bản thân. Hãy tạo kế hoạch học tập 3 tháng cho tôi:\n\nKỹ năng/lĩnh vực muốn học: [KỸ NĂNG]\nMục tiêu cụ thể sau 3 tháng: [MỤC TIÊU]\nThời gian có thể học mỗi ngày: [SỐ GIỜ]\nKiến thức nền hiện tại: [MÔ TẢ TRÌNH ĐỘ HIỆN TẠI]\nNgân sách cho khóa học/tài liệu: [NGÂN SÁCH]\n\nKế hoạch cần bao gồm:\n- Tháng 1: giai đoạn nền tảng (mục tiêu + hoạt động hàng tuần)\n- Tháng 2: giai đoạn thực hành (dự án thực tế)\n- Tháng 3: giai đoạn nâng cao và ứng dụng\n- Nguồn tài liệu miễn phí và trả phí cụ thể\n- Cách đo lường tiến độ sau mỗi tháng\n- Milestone cụ thể để biết mình đang đúng hướng\n\nKế hoạch phải thực tế, không quá tải và có thể thực hiện ngay từ ngày mai.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"nghien-cuu"}'::jsonb, 'Published', 18) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-010', '{"id":"prompt-010","slug":"tao-20-y-tuong-noi-dung-thang-toi","title":"Tạo 20 ý tưởng nội dung cho tháng tới","category":"Viết nội dung","description":"Brainstorm nhanh 20 ý tưởng nội dung đa dạng, phù hợp với thương hiệu và đối tượng.","content":"Bạn là creative director chuyên về content marketing. Hãy brainstorm 20 ý tưởng nội dung cho tháng tới với thông tin:\n\nThương hiệu/cá nhân: [MÔ TẢ]\nNgành: [NGÀNH]\nNền tảng chính: [FACEBOOK / INSTAGRAM / TIKTOK / LINKEDIN]\nĐối tượng mục tiêu: [MÔ TẢ]\nGiọng điệu thương hiệu: [CHUYÊN NGHIỆP / GẦN GŨI / HÀI HƯỚC / ...]\n\nTạo 20 ý tưởng đa dạng, bao gồm:\n- 5 bài giáo dục/tips hữu ích\n- 4 bài kể chuyện (story) cá nhân hoặc khách hàng\n- 3 bài giới thiệu sản phẩm/dịch vụ tự nhiên\n- 3 bài behind-the-scenes hoặc quá trình làm việc\n- 3 bài tương tác (câu hỏi, poll, challenge)\n- 2 bài trending hoặc bắt trend phù hợp\n\nMỗi ý tưởng ghi rõ: tiêu đề gợi ý + dạng bài viết + hook mở đầu + tại sao ý tưởng này phù hợp với đối tượng.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 19) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-011', '{"id":"prompt-011","slug":"dich-tai-lieu-tieng-anh-sang-tieng-viet-tu-nhien","title":"Dịch tài liệu tiếng Anh sang tiếng Việt tự nhiên","category":"Dịch thuật","description":"Dịch văn bản kỹ thuật hoặc tài liệu dài với chất lượng tự nhiên, giữ nguyên nghĩa gốc.","content":"Bạn là dịch giả chuyên nghiệp chuyên dịch tài liệu kinh doanh và kỹ thuật từ tiếng Anh sang tiếng Việt. Hãy dịch đoạn văn bản sau:\n\n[DÁN VĂN BẢN TIẾNG ANH VÀO ĐÂY]\n\nYêu cầu dịch:\n- Dịch tự nhiên như người Việt viết, không dịch từng từ cứng nhắc\n- Giữ nguyên thuật ngữ chuyên ngành nếu tiếng Việt chưa có từ tương đương (có thể để trong ngoặc đơn kèm giải thích)\n- Giữ nguyên cấu trúc đoạn văn, heading và bullet point của bản gốc\n- Tên riêng, tên công ty, tên sản phẩm giữ nguyên tiếng Anh\n- Số liệu, ngày tháng giữ nguyên theo định dạng gốc\n- Sau khi dịch xong, ghi chú các từ/cụm từ bạn không chắc chắn về cách dịch","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"dich-thuat"}'::jsonb, 'Published', 20) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-012', '{"id":"prompt-012","slug":"phan-tich-so-lieu-ban-hang-va-dua-ra-insight","title":"Phân tích số liệu bán hàng và đưa ra insight","category":"Phân tích dữ liệu","description":"Phân tích dữ liệu bán hàng thô và nhận ngay các insight và khuyến nghị hành động.","content":"Bạn là chuyên gia phân tích dữ liệu kinh doanh. Tôi sẽ cung cấp số liệu bán hàng và cần bạn phân tích:\n\n[DÁN SỐ LIỆU VÀO ĐÂY — có thể là bảng Excel, CSV hoặc danh sách]\n\nPhân tích và trả lời:\n1. Tổng quan: doanh thu tổng, đơn hàng, giá trị đơn trung bình\n2. Xu hướng: tăng hay giảm so với kỳ trước? Vì sao?\n3. Sản phẩm tốt nhất: top 3 sản phẩm bán chạy nhất\n4. Sản phẩm cần cải thiện: sản phẩm bán kém, cần xem xét\n5. Thời điểm bán tốt: ngày/giờ/tuần nào bán nhiều nhất\n6. Khách hàng: khách mua lại hay chủ yếu là khách mới\n7. Cơ hội rõ ràng: 3 điều tôi nên làm ngay để tăng doanh thu\n8. Rủi ro: điều gì cần chú ý hoặc có thể gây giảm doanh thu\n\nViết ngắn gọn, dùng bullet points, ưu tiên thông tin thực tế có thể hành động ngay.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"phan-tich-du-lieu"}'::jsonb, 'Published', 21) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-013', '{"id":"prompt-013","slug":"viet-caption-instagram-hap-dan","title":"Viết caption Instagram hấp dẫn","category":"Viết nội dung","description":"Tạo caption Instagram cuốn hút với hook mạnh, nội dung giá trị và hashtag tối ưu.","content":"Bạn là chuyên gia content Instagram với tệp follower trung thành và tỷ lệ tương tác cao. Hãy viết caption cho bài đăng Instagram:\n\nChủ đề/nội dung hình ảnh: [MÔ TẢ HÌNH]\nThông điệp muốn truyền đạt: [THÔNG ĐIỆP]\nĐối tượng theo dõi: [MÔ TẢ]\nPhong cách tài khoản: [LIFESTYLE / BUSINESS / PERSONAL BRAND / ...]\n\nViết caption bao gồm:\n- Dòng đầu tiên: hook cực mạnh (câu hỏi, sự thật gây sốc, hoặc câu nói chạm cảm xúc)\n- Phần thân: nội dung giá trị hoặc câu chuyện ngắn (3-5 câu)\n- Kết thúc: CTA tương tác (hỏi ý kiến, tag bạn bè, hoặc save để xem lại)\n- Hashtag: 10-15 hashtag phù hợp, mix giữa phổ biến và niche\n\nViết 2 phiên bản: một ngắn (dưới 150 từ) và một dài hơn (150-300 từ) để tôi chọn.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 22) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-014', '{"id":"prompt-014","slug":"tao-prompt-midjourney-cho-banner-quang-cao","title":"Tạo prompt Midjourney cho banner quảng cáo","category":"Thiết kế hình ảnh","description":"Tạo prompt tiếng Anh chi tiết để generate hình ảnh banner quảng cáo chuyên nghiệp với Midjourney.","content":"Bạn là chuyên gia viết prompt cho Midjourney, chuyên tạo hình ảnh quảng cáo thương mại chất lượng cao. Hãy viết prompt Midjourney chi tiết cho banner quảng cáo:\n\nSản phẩm/dịch vụ: [MÔ TẢ]\nTông màu thương hiệu: [MÀU SẮC]\nPhong cách thiết kế: [HIỆN ĐẠI / TỐI GIẢN / SANG TRỌNG / ...]\nKhách hàng mục tiêu: [ĐỐI TƯỢNG]\nKích thước: [1:1 / 16:9 / 9:16]\n\nViết prompt theo cấu trúc:\n1. Mô tả cảnh chính (subject)\n2. Phong cách (style, art direction)\n3. Ánh sáng và màu sắc (lighting, color palette)\n4. Chất lượng và thông số kỹ thuật (quality parameters)\n5. Tham số Midjourney: --ar [tỷ lệ] --v 6 --q 2\n\nViết 3 biến thể prompt khác nhau để tôi thử nghiệm. Viết prompt bằng tiếng Anh và giải thích mỗi prompt bằng tiếng Việt.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"thiet-ke-hinh-anh"}'::jsonb, 'Published', 23) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-015', '{"id":"prompt-015","slug":"review-va-cai-thien-doan-code-python","title":"Đánh giá và cải thiện đoạn code Python","category":"Lập trình","description":"Nhờ AI đánh giá code Python, tìm lỗi, tối ưu hiệu suất và đề xuất cải tiến.","content":"Bạn là senior Python developer với 10 năm kinh nghiệm. Hãy đánh giá đoạn code sau và đưa ra phản hồi chi tiết:\n\n```python\n[DÁN CODE VÀO ĐÂY]\n```\n\nPhân tích theo các tiêu chí:\n1. Lỗi (bugs): có lỗi logic hoặc runtime error nào không? Chỉ rõ dòng nào và giải thích\n2. Code style: có tuân theo PEP 8 và best practices Python không?\n3. Hiệu suất: có chỗ nào có thể tối ưu tốc độ hoặc bộ nhớ không?\n4. Bảo mật: có vấn đề bảo mật tiềm ẩn nào không (SQL injection, input validation...)?\n5. Khả năng bảo trì: code có dễ đọc, dễ sửa sau này không?\n6. Edge cases: có trường hợp đặc biệt nào code chưa xử lý?\n\nSau phần phân tích, viết lại đoạn code đã được cải thiện và giải thích những thay đổi bạn đã thực hiện.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"claude","sourceNeedSlug":"lap-trinh"}'::jsonb, 'Published', 24) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-016', '{"id":"prompt-016","slug":"viet-readme-cho-du-an-github","title":"Viết README cho dự án GitHub","category":"Lập trình","description":"Tạo file README chuyên nghiệp và đầy đủ cho dự án mã nguồn mở hoặc cá nhân trên GitHub.","content":"Bạn là developer có kinh nghiệm viết tài liệu kỹ thuật chuyên nghiệp. Hãy viết file README.md cho dự án GitHub sau:\n\nTên dự án: [TÊN]\nMô tả ngắn: [MÔ TẢ]\nCông nghệ sử dụng: [TECH STACK]\nTính năng chính: [TÍNH NĂNG]\nĐối tượng người dùng: [AI DÙNG]\n\nViết README theo cấu trúc chuẩn:\n- Badge (build status, license, version)\n- Mô tả và tính năng nổi bật\n- Screenshot hoặc GIF demo (ghi chú chỗ cần thêm)\n- Yêu cầu hệ thống (Prerequisites)\n- Hướng dẫn cài đặt từng bước\n- Hướng dẫn sử dụng với ví dụ code\n- Cấu trúc thư mục dự án\n- Hướng dẫn đóng góp (Contributing)\n- License\n- Liên hệ tác giả\n\nViết bằng tiếng Anh, dùng Markdown đúng cú pháp, rõ ràng và thân thiện với người mới.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"claude","sourceNeedSlug":"lap-trinh"}'::jsonb, 'Published', 25) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-017', '{"id":"prompt-017","slug":"len-chien-luoc-marketing-san-pham-moi","title":"Lên chiến lược marketing cho sản phẩm mới","category":"Marketing","description":"Xây dựng chiến lược marketing toàn diện từ đầu cho sản phẩm hoặc dịch vụ mới ra mắt.","content":"Bạn là CMO (Giám đốc Marketing) với kinh nghiệm ra mắt sản phẩm thành công tại thị trường Việt Nam. Hãy xây dựng chiến lược marketing cho:\n\nSản phẩm/dịch vụ: [MÔ TẢ]\nGiá bán: [GIÁ]\nThị trường mục tiêu: [ĐỊA LÝ / PHÂN KHÚC]\nNgân sách marketing: [NGÂN SÁCH]\nThời gian ra mắt: [THỜI GIAN]\nĐiểm khác biệt so với đối thủ: [USP]\n\nXây dựng chiến lược bao gồm:\n1. Phân tích thị trường và đối thủ (tóm tắt)\n2. Xác định khách hàng mục tiêu (buyer persona)\n3. Thông điệp marketing chủ đạo\n4. Kênh marketing ưu tiên và lý do\n5. Kế hoạch 3 giai đoạn: pre-launch, launch, post-launch\n6. Phân bổ ngân sách cho từng kênh\n7. KPIs cần đo lường\n8. Rủi ro và kế hoạch dự phòng\n\nƯu tiên các chiến thuật có chi phí thấp nhưng hiệu quả cao phù hợp với SME Việt Nam.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":true,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"marketing"}'::jsonb, 'Published', 26) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-018', '{"id":"prompt-018","slug":"viet-bai-blog-seo-chu-de-ai","title":"Viết bài blog SEO về chủ đề AI","category":"Viết nội dung","description":"Tạo bài viết blog chuyên sâu, tối ưu SEO và thực sự hữu ích cho người đọc về AI.","content":"Bạn là chuyên gia SEO content với kinh nghiệm viết bài blog đạt top Google tại Việt Nam. Hãy viết bài blog SEO về chủ đề:\n\nChủ đề: [CHỦ ĐỀ AI]\nTừ khóa chính: [TỪ KHÓA]\nTừ khóa phụ: [TỪ KHÓA PHỤ]\nĐộ dài mục tiêu: [1500 / 2000 / 3000 từ]\nĐối tượng đọc: [MÔ TẢ NGƯỜI ĐỌC]\n\nBài viết cần:\n- Tiêu đề H1 chứa từ khóa chính, hấp dẫn và dưới 60 ký tự\n- Meta description 150-160 ký tự\n- Mở đầu: đặt vấn đề, nêu những gì bài viết sẽ trả lời\n- Cấu trúc H2/H3 rõ ràng, mỗi heading chứa từ khóa hoặc biến thể\n- Nội dung thực sự hữu ích, có ví dụ cụ thể, không lý thuyết suông\n- Bảng so sánh hoặc bullet points để dễ đọc\n- Internal link placeholder: [LINK: CHỦ ĐỀ LIÊN QUAN]\n- Kết luận tóm tắt và CTA rõ ràng\n- Tối ưu đọc trên mobile: đoạn văn ngắn 2-3 câu","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"claude","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 27) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-019', '{"id":"prompt-019","slug":"tao-outline-khoa-hoc-online","title":"Tạo outline khóa học online","category":"Nghiên cứu","description":"Thiết kế cấu trúc khóa học online chuyên nghiệp với mục tiêu học tập rõ ràng.","content":"Bạn là instructional designer (chuyên gia thiết kế đào tạo) có kinh nghiệm xây dựng các khóa học online thành công. Hãy tạo outline chi tiết cho:\n\nTên khóa học: [TÊN]\nChủ đề: [CHỦ ĐỀ]\nĐối tượng học viên: [MÔ TẢ]\nThời lượng: [SỐ GIỜ]\nĐịnh dạng: [VIDEO / LIVE / HYBRID]\nMức độ: [NGƯỜI MỚI / TRUNG CẤP / NÂNG CAO]\n\nOutline cần bao gồm:\n- Mục tiêu khóa học (3-5 learning outcomes cụ thể, đo được)\n- Ai nên học và ai không nên học\n- Cấu trúc module (chia thành 4-8 module)\n- Mỗi module: tên, mục tiêu, danh sách bài học, bài tập thực hành\n- Thứ tự học lý tưởng (từ đơn giản đến phức tạp)\n- Tài liệu bổ sung cho từng module\n- Bài kiểm tra hoặc dự án cuối khóa\n- Thời lượng ước tính cho từng bài\n\nÁp dụng nguyên tắc adult learning: học bằng thực hành, liên kết với công việc thực tế.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"nghien-cuu"}'::jsonb, 'Published', 28) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-020', '{"id":"prompt-020","slug":"viet-email-nurturing-chuoi-5-buoc","title":"Viết email nurturing chuỗi 5 bước","category":"Marketing","description":"Tạo chuỗi email tự động nuôi dưỡng lead từ lúc đăng ký đến khi sẵn sàng mua hàng.","content":"Bạn là chuyên gia email marketing với tỷ lệ chuyển đổi lead-to-customer trên 15%. Hãy viết chuỗi 5 email nurturing cho:\n\nSản phẩm/dịch vụ: [MÔ TẢ]\nGiá trị cốt lõi: [LỢI ÍCH CHÍNH]\nVấn đề khách hàng: [PAIN POINT]\nThời gian gửi: Email 1 (ngay), 2 (ngày 2), 3 (ngày 4), 4 (ngày 7), 5 (ngày 14)\n\nChuỗi email theo cấu trúc:\n- Email 1: Chào mừng + giao ngay giá trị (không bán hàng)\n- Email 2: Giáo dục về vấn đề họ đang gặp\n- Email 3: Chia sẻ case study / testimonial thực tế\n- Email 4: Xử lý objection phổ biến nhất\n- Email 5: Offer có giới hạn thời gian + CTA mua hàng\n\nMỗi email cần: tiêu đề email (A/B test 2 phiên bản), preview text, nội dung (150-300 từ) và CTA rõ ràng. Giọng văn thân thiện, không spam.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"marketing"}'::jsonb, 'Published', 29) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-021', '{"id":"prompt-021","slug":"phan-tich-feedback-khach-hang","title":"Phân tích feedback khách hàng","category":"Phân tích dữ liệu","description":"Phân tích tổng hợp phản hồi từ khách hàng để tìm ra insight và cải thiện sản phẩm.","content":"Bạn là chuyên gia phân tích trải nghiệm khách hàng (CX analyst). Tôi có tập hợp feedback từ khách hàng và cần bạn phân tích:\n\n[DÁN DANH SÁCH FEEDBACK/REVIEW VÀO ĐÂY]\n\nPhân tích và tổng hợp:\n1. Chủ đề phổ biến: nhóm các feedback theo chủ đề (sản phẩm, giao hàng, dịch vụ...)\n2. Điểm mạnh được khen nhiều nhất: top 3 điều khách hàng hài lòng\n3. Vấn đề được phàn nàn nhiều nhất: top 3 vấn đề cần cải thiện\n4. Feedback bất ngờ: điều gì khách hàng đề cập mà bạn không mong đợi\n5. Cảm xúc tổng thể: tỷ lệ ước tính positive / neutral / negative\n6. Trích dẫn nổi bật: 5 review đáng dùng làm testimonial\n7. Hành động cụ thể: 5 việc cần làm ngay để cải thiện điểm yếu\n\nTrình bày dưới dạng báo cáo ngắn gọn, có thể chia sẻ cho team.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"phan-tich-du-lieu"}'::jsonb, 'Published', 30) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-022', '{"id":"prompt-022","slug":"tao-faq-cho-trang-ban-hang","title":"Tạo FAQ cho trang bán hàng","category":"Viết nội dung","description":"Xây dựng phần Câu hỏi thường gặp thuyết phục, xử lý objection và tăng tỷ lệ mua hàng.","content":"Bạn là chuyên gia conversion rate optimization (CRO) và copywriting bán hàng. Hãy tạo phần FAQ cho trang bán hàng:\n\nSản phẩm/dịch vụ: [MÔ TẢ]\nGiá: [GIÁ]\nCác objection phổ biến từ khách: [LIỆT KÊ NHỮNG GÌ KHÁCH HÀNG HAY THẮC MẮC]\nChính sách hoàn tiền/bảo hành: [CHÍNH SÁCH]\n\nTạo 12-15 câu hỏi FAQ bao gồm:\n- 3-4 câu hỏi về sản phẩm/dịch vụ (tính năng, cách hoạt động)\n- 2-3 câu hỏi về giá và thanh toán\n- 2-3 câu hỏi về quá trình mua/đăng ký\n- 2-3 câu hỏi về kết quả kỳ vọng và thời gian\n- 2-3 câu hỏi xử lý objection (đắt quá, chưa cần, sợ không phù hợp)\n\nMỗi câu trả lời: ngắn gọn (2-4 câu), trực tiếp và tự tin. Không dùng từ ngữ mơ hồ. Kết thúc một số câu trả lời bằng CTA nhẹ nhàng.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 31) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-023', '{"id":"prompt-023","slug":"viet-testimonial-tu-goc-nhin-khach-hang","title":"Viết testimonial từ góc nhìn khách hàng","category":"Marketing","description":"Tạo testimonial chân thực và thuyết phục dựa trên thông tin thực tế từ khách hàng.","content":"Bạn là copywriter chuyên viết social proof và testimonial cho các thương hiệu Việt Nam. Hãy viết testimonial từ góc nhìn khách hàng dựa trên thông tin:\n\nTên khách hàng: [TÊN]\nNghề nghiệp/vai trò: [NGHỀ]\nSản phẩm/dịch vụ đã dùng: [SẢN PHẨM]\nVấn đề trước khi dùng: [VẤN ĐỀ]\nKết quả cụ thể sau khi dùng: [KẾT QUẢ CỤ THỂ]\nThời gian đạt kết quả: [THỜI GIAN]\n\nViết 3 phiên bản testimonial:\n1. Ngắn (50-80 từ): dùng cho quote trên landing page\n2. Trung bình (100-150 từ): dùng cho mạng xã hội\n3. Dài (200-300 từ): dùng cho case study hoặc email marketing\n\nGiọng văn phải tự nhiên như người thật nói chuyện — không quá formal, không sử dụng từ ngữ marketing lộ liễu. Nhấn mạnh kết quả cụ thể và cảm xúc thực sự.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"marketing"}'::jsonb, 'Published', 32) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-024', '{"id":"prompt-024","slug":"nghien-cuu-va-so-sanh-3-cong-cu-ai","title":"Nghiên cứu và so sánh 3 công cụ AI","category":"Nghiên cứu","description":"So sánh toàn diện 3 công cụ AI cụ thể để đưa ra quyết định lựa chọn đúng đắn.","content":"Hãy nghiên cứu và so sánh 3 công cụ AI sau đây dựa trên thông tin mới nhất:\n\nCông cụ cần so sánh:\n1. [CÔNG CỤ 1]\n2. [CÔNG CỤ 2]\n3. [CÔNG CỤ 3]\n\nMục đích sử dụng của tôi: [MÔ TẢ CÁCH BẠN MUỐN DÙNG]\nNgân sách: [MIỄN PHÍ / DƯỚI $20/THÁNG / LINH HOẠT]\n\nSo sánh theo tiêu chí:\n1. Tính năng chính và điểm nổi bật\n2. Giá cả (bản free và bản trả phí)\n3. Ưu điểm so với hai công cụ kia\n4. Hạn chế và nhược điểm\n5. Phù hợp nhất cho ai\n6. Đánh giá của cộng đồng người dùng (nguồn dẫn chứng)\n\nKết luận: với mục đích sử dụng của tôi, bạn khuyên dùng công cụ nào và vì sao? Kèm lý do cụ thể.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"perplexity","sourceNeedSlug":"nghien-cuu"}'::jsonb, 'Published', 33) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-025', '{"id":"prompt-025","slug":"viet-thong-bao-noi-bo-chuyen-nghiep","title":"Viết thông báo nội bộ chuyên nghiệp","category":"Viết nội dung","description":"Soạn thông báo nội bộ rõ ràng, lịch sự và truyền đạt đúng thông điệp đến toàn đội ngũ.","content":"Bạn là chuyên gia truyền thông nội bộ doanh nghiệp. Hãy soạn thông báo nội bộ cho:\n\nChủ đề thông báo: [CHỦ ĐỀ]\nNội dung cần truyền đạt: [NỘI DUNG CHÍNH]\nĐối tượng nhận: [TOÀN CÔNG TY / PHÒNG BAN / NHÓM CỤ THỂ]\nMức độ khẩn cấp: [THÔNG THƯỜNG / QUAN TRỌNG / KHẨN]\nHành động yêu cầu từ người nhận: [NẾU CÓ]\nDeadline (nếu có): [THỜI HẠN]\n\nViết thông báo theo cấu trúc:\n- Tiêu đề rõ ràng, ngắn gọn\n- Mở đầu: mục đích của thông báo\n- Nội dung chính: thông tin cần biết, rõ ràng và đủ\n- Hành động cần thực hiện (nếu có): bullet points từng bước\n- Thời hạn và liên hệ nếu có câu hỏi\n- Chữ ký và chức vụ người gửi\n\nGiọng văn: lịch sự, chuyên nghiệp nhưng không cứng nhắc. Đủ thông tin nhưng không lan man.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"viet-noi-dung"}'::jsonb, 'Published', 34) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-026', '{"id":"prompt-026","slug":"tao-prompt-generate-hinh-anh-san-pham","title":"Tạo prompt để generate hình ảnh sản phẩm","category":"Thiết kế hình ảnh","description":"Tạo prompt AI image chi tiết để tạo ra ảnh sản phẩm chuyên nghiệp không cần studio.","content":"Bạn là chuyên gia product photography và AI image generation. Hãy tạo prompt để generate hình ảnh sản phẩm đẹp bằng AI:\n\nSản phẩm: [MÔ TẢ SẢN PHẨM]\nPhong cách ảnh mong muốn: [STUDIO TRẮNG / LIFESTYLE / OUTDOOR / FLAT LAY]\nMàu nền: [MÀU]\nÁnh sáng: [TỰ NHIÊN / ÁNH ĐÈN STUDIO / CHIAROSCURO]\nĐối tượng mua: [KHÁCH HÀNG]\nNền tảng dùng ảnh: [SHOPEE / WEBSITE / INSTAGRAM]\n\nTạo 3 prompt cho 3 góc chụp khác nhau:\n1. Góc chính diện (hero shot)\n2. Góc đặc tả (detail/close-up)\n3. Góc lifestyle (sản phẩm trong ngữ cảnh sử dụng)\n\nMỗi prompt viết bằng tiếng Anh, bao gồm: mô tả sản phẩm + bố cục ảnh + ánh sáng + phong cách + tham số kỹ thuật. Kèm giải thích tiếng Việt cho từng prompt. Phù hợp với DALL-E 3 hoặc Midjourney.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"thiet-ke-hinh-anh"}'::jsonb, 'Published', 35) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-027', '{"id":"prompt-027","slug":"viet-script-reels-tiktok-60-giay","title":"Viết script cho Reels/TikTok 60 giây","category":"Làm video","description":"Tạo kịch bản video ngắn 60 giây hấp dẫn cho Instagram Reels hoặc TikTok.","content":"Bạn là người sáng tạo nội dung TikTok/Reels với kinh nghiệm tạo ra các video viral và đạt triệu view. Hãy viết script video 60 giây cho:\n\nChủ đề: [CHỦ ĐỀ]\nMục tiêu video: [GIÁO DỤC / GIẢI TRÍ / BÁN HÀNG / XÂY DỰNG THƯƠNG HIỆU]\nNgành nghề/lĩnh vực: [LĨNH VỰC]\nPhong cách: [MẶT-CAM / VOICEOVER / TEXT-ON-SCREEN / HỖN HỢP]\n\nScript theo cấu trúc thời gian:\n- 0-3 giây HOOK: câu mở đầu gây tò mò tức thì (quan trọng nhất!)\n- 3-15 giây: nêu vấn đề hoặc hứa hẹn\n- 15-45 giây: nội dung chính (tip, demo, câu chuyện)\n- 45-55 giây: kết luận hoặc twist bất ngờ\n- 55-60 giây: CTA (follow, comment, lưu video)\n\nCho mỗi đoạn: lời thoại (nói gì) + mô tả hình ảnh/hành động (làm gì trên màn hình) + text overlay (chữ hiện trên màn hình). Viết lời thoại như người nói chuyện thật, không phải đọc bài.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":true,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"lam-video"}'::jsonb, 'Published', 36) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-028', '{"id":"prompt-028","slug":"phan-tich-chien-luoc-affiliate-thanh-cong","title":"Phân tích chiến lược Affiliate thành công","category":"Marketing","description":"Nghiên cứu và học hỏi từ các affiliate marketer thành công trong cùng niche.","content":"Hãy nghiên cứu và phân tích các chiến lược affiliate marketing thành công trong lĩnh vực:\n\nNiche/lĩnh vực: [NICHE CỦA BẠN]\nSản phẩm affiliate: [LOẠI SẢN PHẨM]\nThị trường: [VIỆT NAM / TIẾNG ANH]\nKênh của tôi hiện tại: [BLOG / YOUTUBE / TIKTOK / FACEBOOK]\n\nNghiên cứu và trả lời:\n1. Top affiliate marketer thành công nhất trong niche này hiện đang làm gì?\n2. Kênh nào đang hoạt động tốt nhất cho affiliate trong lĩnh vực này?\n3. Loại nội dung nào có tỷ lệ chuyển đổi cao nhất (review, comparison, tutorial, listicle)?\n4. Chiến lược SEO/organic đang được dùng phổ biến nhất\n5. Cách họ xây dựng lòng tin với audience trước khi bán\n6. Mức commission trung bình trong niche này là bao nhiêu?\n7. 3 bài học quan trọng nhất tôi có thể áp dụng ngay\n\nKèm ví dụ cụ thể và nguồn dẫn chứng cho mỗi điểm.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"perplexity","sourceNeedSlug":"marketing"}'::jsonb, 'Published', 37) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-029', '{"id":"prompt-029","slug":"tu-dong-hoa-quy-trinh-dang-bai-len-nhieu-nen-tang","title":"Tự động hóa quy trình đăng bài lên nhiều nền tảng","category":"Tự động hóa","description":"Thiết kế workflow tự động để đăng nội dung đồng thời lên nhiều mạng xã hội.","content":"Bạn là chuyên gia tự động hóa marketing với kinh nghiệm xây dựng hệ thống đăng bài tự động cho doanh nghiệp. Hãy giúp tôi thiết kế quy trình tự động hóa:\n\nNền tảng muốn đăng: [FACEBOOK / INSTAGRAM / TIKTOK / LINKEDIN / ...]\nTần suất đăng bài: [MỖI NGÀY / 3 LẦN/TUẦN / ...]\nLoại nội dung: [TEXT / ẢNH / VIDEO]\nCông cụ đang dùng hoặc sẵn sàng dùng: [N8N / MAKE / BUFFER / ...]\nNgân sách cho tool: [MIỄN PHÍ / DƯỚI $50/THÁNG]\n\nThiết kế workflow bao gồm:\n1. Quy trình tạo nội dung: từ ý tưởng đến bài viết sẵn sàng đăng\n2. Nơi lưu trữ nội dung chờ đăng (content queue)\n3. Cách lên lịch và tự động đăng lên từng nền tảng\n4. Cách tùy chỉnh nội dung cho từng nền tảng (Facebook khác TikTok)\n5. Theo dõi hiệu suất và báo cáo tự động\n6. Tool và ứng dụng cụ thể cần dùng kèm hướng dẫn kết nối\n\nĐề xuất workflow đơn giản nhất có thể bắt đầu trong 1 ngày, sau đó cải tiến dần.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"tu-dong-hoa"}'::jsonb, 'Published', 38) on conflict (id) do nothing;
insert into public.prompts (id, data, status, "order") values ('prompt-030', '{"id":"prompt-030","slug":"tao-chatbot-faq-don-gian-bang-prompt","title":"Tạo chatbot FAQ đơn giản bằng prompt","category":"Tự động hóa","description":"Xây dựng prompt system để AI trả lời tự động các câu hỏi thường gặp như một chatbot.","content":"Bạn là chuyên gia thiết kế chatbot và prompt engineering. Hãy giúp tôi tạo một system prompt để biến ChatGPT/Claude thành chatbot FAQ cho:\n\nTên doanh nghiệp/thương hiệu: [TÊN]\nLĩnh vực: [LĨNH VỰC]\nSản phẩm/dịch vụ: [MÔ TẢ]\nCác câu hỏi thường gặp: [LIỆT KÊ 10-15 CÂU HỎI PHỔ BIẾN NHẤT]\nTông giọng muốn chatbot dùng: [THÂN THIỆN / CHUYÊN NGHIỆP / TRẺ TRUNG]\nNhững gì chatbot KHÔNG được làm: [GIỚI HẠN]\n\nTạo:\n1. System prompt hoàn chỉnh (đặt vào phần Instructions hoặc System của AI)\n2. Hướng dẫn cập nhật FAQ khi có thay đổi\n3. Cách xử lý câu hỏi ngoài phạm vi (chuyển cho người thật)\n4. Ví dụ test 5 câu hỏi và câu trả lời mẫu\n5. Cách deploy chatbot này lên website hoặc Messenger đơn giản nhất\n\nSystem prompt phải cụ thể, không mơ hồ, để AI luôn trả lời đúng tông giọng và không bịa thông tin.","exampleOutput":"","tags":[],"level":"Cơ bản","tier":"Free","featured":false,"copyCount":0,"status":"Published","sourceToolSlug":"chatgpt","sourceNeedSlug":"tu-dong-hoa"}'::jsonb, 'Published', 39) on conflict (id) do nothing;
